INSERT INTO cms_pages(slug,title,body) VALUES('about','About Noorix Digital Lab','NOORIX DIGITAL LAB is a digital products and subscriptions marketplace. All-in-One Digital Solutions Under One Roof.');
INSERT INTO cms_pages(slug,title,body) VALUES('terms','Terms of Service','DRAFT — have this reviewed before launch. By using this website you agree to these terms. Digital products are delivered electronically. Prices are in PKR. We may refuse or cancel orders where fraud or misuse is suspected. Wallet funds are usable only for purchases on this website.');
INSERT INTO cms_pages(slug,title,body) VALUES('privacy','Privacy Policy','DRAFT — have this reviewed before launch. We store the information you give us (name, email, phone, orders, support messages, payment proofs) to operate your account. We do not sell personal data. Contact us to request correction or deletion.');
INSERT INTO cms_pages(slug,title,body) VALUES('refund','Refund Policy','DRAFT — have this reviewed before launch. Refunds are only available for products marked as refund-eligible and only where the product has not been successfully used. Approved refunds are credited to your Noorix wallet. Wallet deposits are not refundable to the original payment method.');
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_0','How long does delivery take?','Automatic products are delivered instantly. Manual products are delivered by our team, normally within the time shown on the product.',0);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_1','How do I add funds?','Open Wallet, choose Add Funds, pay by Bank Transfer, Easypaisa or JazzCash, and submit the transaction ID with a screenshot. Funds appear after an admin verifies the payment.',1);
INSERT INTO faqs(id,question,answer,sort_order) VALUES('faq_2','Can I get a refund?','Only products marked refund-eligible can be refunded, according to the Refund Policy. Open a support ticket from your order.',2);
